  "compact-style": "'use client';\n\nimport React from 'react';\nimport { SearchOutlined } from '@ant-design/icons';\nimport { Button, Input, Select, Space } from '@ceebee/ui/client';\n\nconst { Search } = Input;\n\nconst options = [\n  {\n    value: 'zhejiang',\n    label: 'Zhejiang',\n  },\n  {\n    value: 'jiangsu',\n    label: 'Jiangsu',\n  },\n];\n\nconst App: React.FC = () => (\n  <Space vertical size=\"medium\">\n    <Space.Compact>\n      <Input defaultValue=\"26888888\" />\n    </Space.Compact>\n    <Space.Compact>\n      <Input style={{ width: '20%' }} defaultValue=\"0571\" />\n      <Input style={{ width: '80%' }} defaultValue=\"26888888\" />\n    </Space.Compact>\n    <Space.Compact>\n      <Space.Addon>https://</Space.Addon>\n      <Search placeholder=\"input search text\" allowClear />\n    </Space.Compact>\n    <Space.Compact style={{ width: '100%' }}>\n      <Input defaultValue=\"Combine input and button\" />\n      <Button type=\"primary\">Submit</Button>\n    </Space.Compact>\n    <Space.Compact>\n      <Select defaultValue=\"Zhejiang\" options={options} />\n      <Input defaultValue=\"Xihu District, Hangzhou\" />\n    </Space.Compact>\n    <Space.Compact size=\"large\">\n      <Space.Addon>\n        <SearchOutlined />\n      </Space.Addon>\n      <Input placeholder=\"large size\" />\n      <Input placeholder=\"another input\" />\n    </Space.Compact>\n  </Space>\n);\n\nexport default App;\n",
  "focus": "'use client';\n\nimport React, { useRef, useState } from 'react';\nimport type { InputRef } from '@ceebee/ui/client';\nimport { Button, Input, Space, Switch } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const inputRef = useRef<InputRef>(null);\n  const [input, setInput] = useState(true);\n\n  const sharedProps = {\n    style: { width: '100%' },\n    defaultValue: 'Ceebee loves you!',\n    ref: inputRef,\n  };\n\n  return (\n    <Space vertical style={{ width: '100%' }}>\n      <Space wrap>\n        <Button\n          onClick={() => {\n            inputRef.current?.focus({ cursor: 'start' });\n          }}\n        >\n          Focus at first\n        </Button>\n        <Button\n          onClick={() => {\n            inputRef.current?.focus({ cursor: 'end' });\n          }}\n        >\n          Focus at last\n        </Button>\n        <Button\n          onClick={() => {\n            inputRef.current?.focus({ cursor: 'all' });\n          }}\n        >\n          Focus to select all\n        </Button>\n        <Button\n          onClick={() => {\n            inputRef.current?.focus({ preventScroll: true });\n          }}\n        >\n          Focus prevent scroll\n        </Button>\n        <Switch\n          checked={input}\n          checkedChildren=\"Input\"\n          unCheckedChildren=\"TextArea\"\n          onChange={() => {\n            setInput((prev) => !prev);\n          }}\n        />\n      </Space>\n      <br />\n      {input ? <Input {...sharedProps} /> : <Input.TextArea {...sharedProps} />}\n    </Space>\n  );\n};\n\nexport default App;\n",
  "otp": "'use client';\n\nimport React from 'react';\nimport { Flex, Input, Typography } from '@ceebee/ui/client';\nimport type { GetProps } from '@ceebee/ui/client';\n\ntype OTPProps = GetProps<typeof Input.OTP>;\n\nconst { Title } = Typography;\n\nconst App: React.FC = () => {\n  const onChange: OTPProps['onChange'] = (text) => {\n    console.log('onChange:', text);\n  };\n\n  const onInput: OTPProps['onInput'] = (value) => {\n    console.log('onInput:', value);\n  };\n\n  const sharedProps: OTPProps = {\n    onChange,\n    onInput,\n  };\n\n  return (\n    <Flex gap=\"medium\" align=\"flex-start\" vertical>\n      <Title level={5}>With formatter (Upcase)</Title>\n      <Input.OTP formatter={(str) => str.toUpperCase()} {...sharedProps} />\n      <Title level={5}>With Disabled</Title>\n      <Input.OTP disabled {...sharedProps} />\n      <Title level={5}>With Length (8)</Title>\n      <Input.OTP length={8} {...sharedProps} />\n      <Title level={5}>With variant</Title>\n      <Input.OTP variant=\"filled\" {...sharedProps} />\n      <Title level={5}>With custom display character</Title>\n      <Input.OTP mask=\"🔒\" {...sharedProps} />\n      <Title level={5}>With custom ReactNode separator</Title>\n      <Input.OTP separator={<span>/</span>} {...sharedProps} />\n      <Title level={5}>With custom function separator</Title>\n      <Input.OTP\n        separator={(i) => <span style={{ color: i & 1 ? 'red' : 'blue' }}>—</span>}\n        {...sharedProps}\n      />\n    </Flex>\n  );\n};\n\nexport default App;\n",
  "password-input": "'use client';\n\nimport React from 'react';\nimport { EyeInvisibleOutlined, EyeTwoTone } from '@ant-design/icons';\nimport { Button, Input, Space } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [passwordVisible, setPasswordVisible] = React.useState(false);\n\n  return (\n    <Space vertical>\n      <Input.Password placeholder=\"input password\" />\n      <Input.Password\n        placeholder=\"input password\"\n        iconRender={(visible) => (visible ? <EyeTwoTone /> : <EyeInvisibleOutlined />)}\n      />\n      <Space>\n        <Input.Password\n          placeholder=\"input password\"\n          visibilityToggle={{ visible: passwordVisible, onVisibleChange: setPasswordVisible }}\n        />\n        <Button style={{ width: 80 }} onClick={() => setPasswordVisible((prevState) => !prevState)}>\n          {passwordVisible ? 'Hide' : 'Show'}\n        </Button>\n      </Space>\n      <Input.Password disabled placeholder=\"disabled input password\" />\n    </Space>\n  );\n};\n\nexport default App;\n",
