  "tooltip": "'use client';\n\nimport React, { useState } from 'react';\nimport { Input, Tooltip } from '@ceebee/ui/client';\nimport { createStyles } from 'antd-style';\n\nconst useStyles = createStyles((props) => {\n  const { css, prefixCls, cssVar } = props;\n  return {\n    numericInput: css`\n      .${prefixCls}-tooltip-container {\n        min-width: 32px;\n        min-height: 38px;\n      }\n    `,\n    numericInputTitle: css`\n      font-size: ${cssVar.fontSize};\n    `,\n  };\n});\n\ninterface NumericInputProps {\n  style: React.CSSProperties;\n  value: string;\n  onChange: (value: string) => void;\n}\n\nconst formatNumber = (value: number) => new Intl.NumberFormat().format(value);\n\nconst NumericInput: React.FC<NumericInputProps> = (props) => {\n  const { value, onChange } = props;\n\n  const { styles } = useStyles();\n\n  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const { value: inputValue } = e.target;\n    const reg = /^-?\\d*(\\.\\d*)?$/;\n    if (reg.test(inputValue) || inputValue === '' || inputValue === '-') {\n      onChange(inputValue);\n    }\n  };\n\n  // '.' at the end or only '-' in the input box.\n  const handleBlur: React.FocusEventHandler<HTMLInputElement> = () => {\n    let valueTemp = value;\n    if (value.charAt(value.length - 1) === '.' || value === '-') {\n      valueTemp = value.slice(0, -1);\n    }\n    onChange(valueTemp.replace(/0*(\\d+)/, '$1'));\n  };\n\n  const title = value ? (\n    <span className={styles.numericInputTitle}>\n      {value !== '-' ? formatNumber(Number(value)) : '-'}\n    </span>\n  ) : (\n    'Input a number'\n  );\n\n  return (\n    <Tooltip\n      destroyOnHidden\n      trigger={['focus']}\n      title={title}\n      placement=\"topLeft\"\n      classNames={{ root: styles.numericInput }}\n    >\n      <Input\n        {...props}\n        onChange={handleChange}\n        onBlur={handleBlur}\n        placeholder=\"Input a number\"\n        maxLength={16}\n      />\n    </Tooltip>\n  );\n};\n\nconst App: React.FC = () => {\n  const [value, setValue] = useState('');\n  return <NumericInput style={{ width: 120 }} value={value} onChange={setValue} />;\n};\n\nexport default App;\n",
